    check_kpi: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Project name */
                project: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "pipeline": {
                 *         "apiVersion": "joinedcontext.com/v1alpha2",
                 *         "kind": "Pipeline",
                 *         "metadata": {
                 *           "name": "parking-per-stop"
                 *         },
                 *         "spec": {
                 *           "class": "scheduled",
                 *           "outputs": [
                 *             {
                 *               "targetEndpoint": "urn:ngsi-ld:Endpoint:hel.fi:helsinki-kpi:kpi-writer"
                 *             }
                 *           ],
                 *           "schedule": "0 * * * *",
                 *           "sources": [
                 *             {
                 *               "endpointRef": {
                 *                 "kind": "Endpoint",
                 *                 "name": "helsinki-parking"
                 *               },
                 *               "name": "parking",
                 *               "query": {
                 *                 "attrs": [
                 *                   "occupiedSpotNumber",
                 *                   "district"
                 *                 ],
                 *                 "type": "ParkingSite"
                 *               }
                 *             },
                 *             {
                 *               "endpointRef": {
                 *                 "kind": "Endpoint",
                 *                 "name": "helsinki-transit"
                 *               },
                 *               "name": "stops",
                 *               "query": {
                 *                 "attrs": [
                 *                   "district"
                 *                 ],
                 *                 "type": "TransitStop"
                 *               }
                 *             }
                 *           ],
                 *           "steps": [
                 *             {
                 *               "kind": "kpi",
                 *               "kpi": {
                 *                 "formula": "sum(parking.occupiedSpotNumber) / count(stops)",
                 *                 "join": {
                 *                   "by": "area",
                 *                   "keys": {
                 *                     "parking": "district",
                 *                     "stops": "district"
                 *                   }
                 *                 },
                 *                 "name": "parking-per-stop",
                 *                 "unitCode": "C62"
                 *               }
                 *             }
                 *           ]
                 *         }
                 *       },
                 *       "preview": true
                 *     }
                 */
                "application/json": components["schemas"]["KpiCheckRequest"];
            };
        };
        responses: {
            /** @description The problems, the sources and, when asked, the preview */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["KpiChecked"];
                };
            };
            /** @description The body is not a Pipeline of this project */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ProblemDetails"];
                };
            };
            /** @description Not signed in */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ProblemDetails"];
                };
            };
            /** @description No propose on Pipeline here, or a workload token */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ProblemDetails"];
                };
            };
            /** @description No such project */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ProblemDetails"];
                };
            };
        };
    };
